(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-332":{scenario:{company:"Gió Mùa Online Mart",supervisor:{name:"Hoàng Gia Bảo",role:{vi:"Giám đốc Ngành hàng",en:"Head of Category"}},ref_code:"AR-0917",title:{vi:"Đúng quyết định. Đúng biên lãi. Đúng hồ sơ.",en:"Right call. Right margin. Right paperwork."},brief:{vi:"Bạn rà soát danh mục quý 4 ngành gia dụng AR-0917. Nồi cơm điện RC-18: 90 ngày nhận 1000 chiếc, bán 180; tồn 820 chiếc, tuổi tồn 135 ngày; hàng mua đứt, nhà cung cấp không nhận trả. Chính sách: sell-through 90 ngày dưới 25% và tuổi tồn trên 120 ngày thì MARKDOWN để xả; chỉ DELIST khi tồn dưới 50 chiếc; từ 25% trở lên thì KEEP. Giá vốn 459000 đồng; khi xả phải giữ biên lợi nhuận gộp tối thiểu 10%. Sửa quyết định SKU và giá xả tối thiểu, rồi lập báo cáo có căn cứ.",en:"You are reviewing the Q4 home appliance assortment AR-0917. Rice cooker RC-18: 1000 units received and 180 sold in 90 days; 820 in stock aged 135 days; bought outright with no supplier returns. Policy: 90-day sell-through below 25% and stock age over 120 days means MARKDOWN to clear; DELIST only when stock is below 50 units; 25% or more means KEEP. Cost 459000 VND; a clearance must keep at least a 10% gross margin. Correct the SKU decision and the minimum clearance price, then write an evidence-based report."},reference_title:{vi:"Chính sách rà soát danh mục & bảng tính giá xả đã duyệt · AR-0917",en:"Approved assortment review policy & clearance price sheet · AR-0917"},fields:[{id:"SKU_ACTION",label:{vi:"Quyết định với SKU RC-18",en:"Decision for SKU RC-18"},initial:"DELIST",expected:"MARKDOWN",choices:["KEEP","DELIST","MARKDOWN"],reference:"Chính sách rà soát danh mục",hint:{vi:"Tính sell-through, đối chiếu tuổi tồn và kiểm tra điều kiện tồn kho bắt buộc trước khi loại SKU.",en:"Compute sell-through, compare stock age and check the stock condition required before delisting."}},{id:"FLOOR_PRICE",label:{vi:"Giá xả tối thiểu chưa VAT (VND)",en:"Minimum clearance price excl. VAT (VND)"},initial:"504900",expected:"510000",reference:"Bảng tính giá xả",ref_value:{vi:"Giá vốn 459000 đồng; biên lợi nhuận gộp tối thiểu 10% tính trên giá bán chưa VAT",en:"Cost 459000 VND; minimum gross margin 10% on the selling price excl. VAT"},hint:{vi:"Bản nháp cộng 10% lên giá vốn; biên lợi nhuận gộp lại được tính trên giá bán.",en:"The draft adds 10% to cost; gross margin is measured on the selling price."}}],sop32:{vi:"Giá xả tối thiểu = giá vốn / (1 - biên lợi nhuận gộp tối thiểu); biên tính trên giá bán chưa VAT, không phải tỷ lệ cộng thêm trên giá vốn. Làm tròn đến đồng (mô phỏng).",en:"Minimum clearance price = cost / (1 - minimum gross margin); margin is measured on the selling price excl. VAT, not as a markup on cost. Round to the dong (training)."},context:{label:"CATEGORY / AR-0917",metrics:[{label:{vi:"Nhận / bán 90 ngày",en:"90-day received / sold"},value:"1000 / 180"},{label:{vi:"Tuổi tồn kho",en:"Stock age"},value:"135 d"},{label:{vi:"Tồn kho hiện tại",en:"Stock on hand"},value:"820"},{label:{vi:"Giá vốn",en:"Unit cost"},value:"459,000 VND"}]},crisis:{vi:"Nhà cung cấp dòng nồi cơm nhập khẩu mới đề nghị: “Cho lên sàn trước đợt 12.12 đi, giấy chứng nhận hợp quy an toàn điện bọn tôi bổ sung sau. Chúng tôi tài trợ thêm 200 triệu phí trưng bày.”",en:"The supplier of a new imported rice cooker line proposes: “List it before 12.12 and we will add the electrical safety conformity certificate later. We will pay an extra 200 million in display fees.”"},options:{safe:{vi:"Không mở bán khi chưa đủ chứng nhận hợp quy và hồ sơ chất lượng, báo Giám đốc Ngành hàng; đề xuất lịch ra mắt sau khi pháp chế và bộ phận chất lượng kiểm tra đủ hồ sơ.",en:"Do not list without the conformity certificate and quality file, inform the Head of Category; propose a launch date after legal and quality have checked the full file."},shortcut:{vi:"Mở bán trước để nhận tài trợ, gỡ sản phẩm nếu có người kiểm tra.",en:"List it now to get the sponsorship and take it down if anyone checks."},wait:{vi:"Không trả lời nhà cung cấp và để nhóm vận hành tự quyết có đăng hay không.",en:"Ignore the supplier and let operations decide whether to list it."}},questions:{vi:["Vì sao RC-18 phải MARKDOWN chứ không phải DELIST hay KEEP? Chỉ số và điều khoản mua hàng nào quyết định?","Trình bày cách tính giá xả tối thiểu và rủi ro khi mở bán hàng chưa có chứng nhận hợp quy."],en:["Why must RC-18 be MARKDOWN rather than DELIST or KEEP? Which metric and purchase term decide it?","Explain the minimum clearance price calculation and the risk of listing goods without a conformity certificate."]},hints:{vi:["Đặt bản nháp cạnh chính sách rà soát, tính sell-through rồi kiểm tra từng điều kiện theo thứ tự.","Áp dụng công thức SOP mục 3.2: biên lợi nhuận tính trên giá bán, không phải trên giá vốn.","Đọc lại SOP mục 4.2: hàng hóa thiếu hồ sơ hợp quy không được mở bán dù có tài trợ."],en:["Place the draft next to the review policy, compute sell-through and check each condition in order.","Apply the SOP 3.2 formula: margin is measured on selling price, not on cost.","Re-read SOP 4.2: goods missing conformity papers may not be listed, sponsorship or not."]}},learning:{summary:{vi:"Quản lý ngành hàng thương mại điện tử chịu trách nhiệm doanh thu, lợi nhuận và trải nghiệm mua sắm của một ngành hàng: xây dựng danh mục sản phẩm, chọn và đàm phán với nhà cung cấp, định giá, lập kế hoạch khuyến mại, kiểm soát tồn kho và hiệu quả vốn. Nghề đòi hỏi tư duy phân tích dữ liệu bán hàng, hiểu khách hàng và đối thủ, đàm phán thương mại vững và trách nhiệm bảo đảm hàng hóa hợp pháp, an toàn cho người tiêu dùng.",en:"An e-commerce category manager owns the revenue, profit and shopping experience of a category: building the assortment, selecting and negotiating with suppliers, pricing, planning promotions and controlling stock and capital efficiency. The role needs analytical thinking on sales data, customer and competitor insight, strong commercial negotiation and responsibility for lawful, safe products."},responsibilities:{vi:["Xây dựng chiến lược, vai trò ngành hàng và mục tiêu doanh thu, biên lợi nhuận.","Lập danh mục sản phẩm, thêm hoặc loại SKU dựa trên dữ liệu bán hàng và nhu cầu khách.","Đàm phán giá, chiết khấu, hỗ trợ marketing, điều kiện trả hàng và thanh toán với nhà cung cấp.","Định giá, lập kế hoạch khuyến mại và xả hàng chậm luân chuyển có kiểm soát biên lợi nhuận.","Theo dõi tồn kho, sell-through, GMROI và kiểm soát hồ sơ pháp lý, chất lượng sản phẩm."],en:["Set the category strategy, role and revenue and margin targets.","Build the assortment and add or delist SKUs based on sales data and customer demand.","Negotiate prices, discounts, marketing support, return and payment terms with suppliers.","Price products and plan promotions and slow-mover clearance with margin control.","Track stock, sell-through and GMROI and control product legal and quality files."]},competencies:[{name:{vi:"Phân tích danh mục",en:"Assortment analysis"},desc:{vi:"Đọc dữ liệu bán, tồn, tìm kiếm để biết SKU nào cần giữ, đẩy, xả hay loại.",en:"Read sales, stock and search data to decide which SKUs to keep, push, clear or delist."}},{name:{vi:"Đàm phán nhà cung cấp",en:"Supplier negotiation"},desc:{vi:"Thương lượng điều khoản cân bằng giá vốn, hỗ trợ bán hàng và rủi ro tồn kho.",en:"Negotiate terms that balance cost, sales support and stock risk."}},{name:{vi:"Định giá & biên lợi nhuận",en:"Pricing & margin"},desc:{vi:"Tính đúng biên lợi nhuận, markup, giá xả và tác động của khuyến mại.",en:"Compute margin, markup, clearance price and promotion impact correctly."}},{name:{vi:"Quản trị tồn kho & vốn",en:"Inventory & capital control"},desc:{vi:"Lập kế hoạch mua theo ngân sách, hạn chế tồn ứ và hàng chậm luân chuyển.",en:"Plan buying within budget and limit overstock and slow movers."}},{name:{vi:"Tuân thủ chất lượng",en:"Product compliance"},desc:{vi:"Chỉ mở bán hàng đủ hồ sơ hợp quy, nhãn mác, nguồn gốc theo quy định.",en:"List only goods with complete conformity, labeling and origin documents."}}],knowledge:{vi:["Quy trình quản trị ngành hàng 8 bước: định nghĩa, vai trò, đánh giá, thẻ điểm, chiến lược, chiến thuật, triển khai, rà soát.","Chỉ số danh mục: sell-through, tuổi tồn, số ngày tồn, GMROI, biên lợi nhuận gộp và phân biệt margin với markup.","Luật Chất lượng sản phẩm, hàng hóa và quy chuẩn kỹ thuật quốc gia: hàng thuộc diện quản lý phải chứng nhận, công bố hợp quy trước khi lưu thông.","Luật Bảo vệ quyền lợi người tiêu dùng 2023 và quy định thương mại điện tử về thông tin sản phẩm trung thực.","Điều khoản thương mại với nhà cung cấp: mua đứt, ký gửi, chiết khấu, phí trưng bày, điều kiện đổi trả."],en:["The 8-step category management process: definition, role, assessment, scorecard, strategy, tactics, implementation, review.","Assortment metrics: sell-through, stock age, days of stock, GMROI, gross margin and margin versus markup.","Product quality law and national technical regulations: regulated goods need conformity certification and declaration before sale.","Consumer Protection Law 2023 and e-commerce rules on truthful product information.","Supplier trade terms: outright purchase, consignment, discounts, display fees and return conditions."]},tools:["Hệ thống ERP / quản lý mua hàng","BI phân tích ngành hàng","Công cụ theo dõi giá thị trường","Bảng tính kế hoạch mua (OTB)","Cổng hồ sơ nhà cung cấp"],kpis:{vi:["Doanh thu và tăng trưởng của ngành hàng.","Biên lợi nhuận gộp và GMROI.","Tỷ lệ giá trị tồn kho quá 120 ngày.","Tỷ lệ hết hàng của các SKU chủ lực."],en:["Category revenue and growth.","Gross margin and GMROI.","Share of stock value older than 120 days.","Out-of-stock rate of core SKUs."]},day:[{time:"08:30",vi:"Xem bảng BI doanh số, tồn kho và giá thị trường của ngành hàng.",en:"Review category sales, stock and market price dashboards."},{time:"10:00",vi:"Đàm phán điều khoản quý mới với một nhà cung cấp chủ lực.",en:"Negotiate next quarter's terms with a key supplier."},{time:"13:30",vi:"Rà soát danh mục, đề xuất thêm, xả hoặc loại SKU theo chính sách.",en:"Review the assortment and propose adds, clearances or delists per policy."},{time:"15:00",vi:"Kiểm tra hồ sơ hợp quy, nhãn mác của sản phẩm mới trước khi mở bán.",en:"Check conformity and labeling files of new products before listing."},{time:"17:00",vi:"Hoàn thiện kế hoạch khuyến mại và kế hoạch mua cho tháng tới.",en:"Finalize next month's promotion and buying plans."}],mistakes:{vi:["Nhầm biên lợi nhuận gộp với tỷ lệ cộng thêm trên giá vốn khi định giá.","Loại SKU mua đứt khi còn tồn lớn không thể trả nhà cung cấp.","Mở bán hàng chưa đủ hồ sơ hợp quy vì áp lực doanh số hoặc tài trợ."],en:["Confusing gross margin with markup on cost when pricing.","Delisting an outright-purchase SKU while large unreturnable stock remains.","Listing goods without conformity papers because of sales pressure or sponsorship."]},career:[{vi:"Trợ lý ngành hàng",en:"Category assistant"},{vi:"Chuyên viên mua hàng ngành hàng",en:"Category buyer"},{vi:"Quản lý ngành hàng",en:"Category manager"},{vi:"Giám đốc ngành hàng / Giám đốc mua hàng",en:"Head of category or buying director"}],glossary:[{term:"Sell-through",vi:"Tỷ lệ số lượng bán ra trên số lượng nhận trong kỳ.",en:"Units sold divided by units received in the period."},{term:"GMROI",vi:"Lợi nhuận gộp tạo ra trên mỗi đồng tồn kho bình quân tính theo giá vốn.",en:"Gross margin earned per unit of average inventory at cost."},{term:"Markdown",vi:"Giảm giá có kế hoạch để xả hàng chậm luân chuyển hoặc cuối mùa.",en:"A planned price cut to clear slow-moving or end-of-season stock."},{term:"OTB",vi:"Ngân sách mua còn được phép trong kỳ sau khi trừ tồn kho và đơn đã đặt.",en:"Open-to-buy: remaining buying budget after stock and open orders."},{term:"Assortment",vi:"Danh mục sản phẩm: tập hợp SKU, mức giá, thương hiệu mà ngành hàng chào bán.",en:"The set of SKUs, price points and brands a category offers."}],quiz:[{q:{vi:"Giá vốn 360000 đồng, cần biên lợi nhuận gộp 20% trên giá bán. Giá bán là bao nhiêu?",en:"Cost is 360000 VND and a 20% gross margin on price is required. What is the price?"},options:{vi:["432000 đồng","450000 đồng","380000 đồng","460000 đồng"],en:["432000 VND","450000 VND","380000 VND","460000 VND"]},answer:1,explain:{vi:"360000 / (1 - 20%) = 450000; 432000 là markup 20% trên giá vốn, chỉ cho biên 16,7%.",en:"360000 / (1 - 20%) = 450000; 432000 is a 20% markup giving only 16.7% margin."}},{q:{vi:"Sell-through 90 ngày được tính như thế nào?",en:"How is 90-day sell-through calculated?"},options:{vi:["Tồn cuối kỳ / tồn đầu kỳ","Doanh thu / giá vốn","Số bán / số tồn cuối kỳ","Số lượng bán / số lượng nhận trong kỳ"],en:["Closing stock / opening stock","Revenue / cost","Units sold / closing stock","Units sold / units received in the period"]},answer:3,explain:{vi:"Sell-through cho biết bao nhiêu phần hàng nhận về đã bán được, ví dụ 180 / 1000 = 18%.",en:"Sell-through shows how much received stock has sold, e.g. 180 / 1000 = 18%."}},{q:{vi:"Nhà cung cấp đề nghị mở bán trước, bổ sung hồ sơ hợp quy sau, kèm tài trợ lớn. Bạn làm gì?",en:"A supplier asks to list now and add conformity papers later, with a big sponsorship. What do you do?"},options:{vi:["Nhận tài trợ và mở bán ngay","Mở bán ở mục ít người xem","Từ chối mở bán đến khi đủ hồ sơ, báo cáo và lên lịch ra mắt hợp lệ","Để nhà cung cấp tự đăng"],en:["Take the money and list now","List it in a low-traffic section","Refuse until the file is complete, escalate and schedule a lawful launch","Let the supplier list it themselves"]},answer:2,explain:{vi:"Hàng thuộc diện quản lý chưa hợp quy có thể gây mất an toàn và bị xử phạt; tài trợ không thay được hồ sơ.",en:"Regulated goods without conformity may be unsafe and fined; sponsorship never replaces paperwork."}},{q:{vi:"Chỉ số GMROI đo điều gì?",en:"What does GMROI measure?"},options:{vi:["Lợi nhuận gộp trên mỗi đồng tồn kho bình quân theo giá vốn","Tốc độ tăng trưởng doanh thu","Tỷ lệ khách quay lại mua","Chi phí quảng cáo trên doanh thu"],en:["Gross margin per unit of average inventory at cost","Revenue growth rate","Repeat purchase rate","Ad spend over revenue"]},answer:0,explain:{vi:"GMROI cho biết vốn tồn kho sinh lời ra sao, giúp quyết định giữ, xả hay loại SKU.",en:"GMROI shows how well inventory capital earns, guiding keep, clear or delist decisions."}}],tools_en:["ERP / procurement system","Category analytics BI","Market price tracking tool","Open-to-buy (OTB) planning spreadsheet","Supplier information portal"]}}})})(window.KKR);
